\set ON_ERROR_STOP on
BEGIN;
DO $$ BEGIN IF current_database() NOT LIKE 'moralles_phase7_test_%' OR inet_server_addr() IS DISTINCT FROM '127.0.0.1'::inet THEN RAISE EXCEPTION 'LOCAL_FIXTURES_ONLY'; END IF; END $$;
CREATE TEMP TABLE results(label text);
GRANT ALL ON results TO anon,authenticated,service_role;
CREATE FUNCTION pg_temp.ok(value boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF value IS DISTINCT FROM true THEN RAISE EXCEPTION 'TEST FAILED: %',label; END IF; INSERT INTO results VALUES(label); END $$;
CREATE FUNCTION pg_temp.denied(statement text,label text,expected_state text DEFAULT '42501') RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE statement; EXCEPTION WHEN OTHERS THEN IF SQLSTATE=expected_state THEN INSERT INTO results VALUES(label); RETURN; END IF; RAISE; END; RAISE EXCEPTION 'TEST FAILED expected denial: %',label; END $$;
CREATE FUNCTION pg_temp.context(actor integer,unit integer DEFAULT 1) RETURNS void LANGUAGE plpgsql AS $$ BEGIN
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',format('a7000000-0000-4000-8000-%s',lpad(actor::text,12,'0')),'role','authenticated')::text,true);
 PERFORM set_config('request.headers',jsonb_build_object('x-company-id',format('b7000000-0000-4000-8000-%s',lpad(unit::text,12,'0')))::text,true);
END $$;
